#!/usr/bin/env python3
"""Selected Ukrainian icons; source conflicts and qualified attributions retained."""
import copy, importlib.util, json
from pathlib import Path
sp=importlib.util.spec_from_file_location('campaign',Path(__file__).with_name('creators-deep-4h-20261010.py'))
x=importlib.util.module_from_spec(sp);sp.loader.exec_module(x);x.configure('yov-kondzelevych')
plan=x.r.load(x.RUN/'research-selection.json.gz');allrows=plan['rows']
volurl='https://volart.com.ua/art/konzelevyz/'
vol=x.r.load(x.RUN/'native-objects'/(x.r.sha(volurl.encode())+'.json'))
receipts={k:x.r.load(x.RUN/f) for k,f in dict(restoration='restoration-catalogue-receipt.json',helytovych='helytovych-receipt.json',volyn2017='volyn-2017-receipt.json',catalogue='volyn-catalogue-receipt.json').items()}
publishers=dict(restoration='National Research Restoration Centre of Ukraine, Lviv branch: Revived Masterpieces',helytovych='Volyn Local History Museum, Volyn Icon volume 25 (2018), Maria Helytovych, pp. 77–89',volyn2017='Volyn Local History Museum, Volyn Icon volume 24 (2017), L. Obukhovych',catalogue='Volyn Local History Museum: Volyn Icons of the Sixteenth–Eighteenth Centuries, collection catalogue (2018)')
def pdf(key,locator,facts,note,acc=None):
 rc=receipts[key]
 return dict(url=rc['url'],publisher=publishers[key],receipt=rc,locator=locator,record_id=acc,facts=facts,review=note,confidence=.97)
data={
1:dict(title="Baptism of Christ",note="The selected WikiArt and Volart photographs show the identical Baptism composition. WikiArt supplies 1696 but calls the medium fresco; Volart associates the composition with the Zahoriv/Voshchatyn material, and the museum article documents the 1696 painted altar. The precise panel-to-ensemble placement is not established by the available full-altar photograph. Retain the explicit WikiArt year as source-reported, but leave medium unknown rather than repeat an unverified fresco label. No museum inventory or accepted holding is inferred.",medium=None,dimensions=None),
4:dict(title='Christ the Teacher (Maniava iconostasis)',year=1698,medium='tempera and oil on wood, gilding',dimensions='147 × 93 × 2.5 cm',acc='І-2292',note='The unframed WikiArt photograph and the restored catalogue plate show the same individual panel, including book, blessing hand, engraved ground and figure. Restoration catalogue entry 46 and the transcribed signature date this panel 1698. Helytovych p. 78 has 1697 in prose, but p. 86 explicitly reads the 1698 date twice in the inscription. Preserve that source discrepancy. This is an individual panel of the already catalogued Maniava/Bohorodchany ensemble, not another whole iconostasis.'),
5:dict(title='Mother of God Hodegetria (Maniava iconostasis)',medium='tempera and oil on wood, gilding and engraved gesso',dimensions=None,acc='І-2289',note='Exact panel composition matched across the older unframed WikiArt photograph, restored catalogue plate 47 and the current National Museum in Lviv object page. The museum gives 152 × 93 × 3 cm, while the restoration catalogue gives 147 × 92.5 × 2.5 cm. Preserve both measurements in citations and leave the new dimension field unknown. This panel is distinct from the whole ensemble already present.'),
6:dict(title='Ascension (Maniava iconostasis)',year=1705,medium='tempera and oil on wood, gilding',dimensions='235 × 141 × 2.5 cm',acc='КН-36615; І-2305',note='Exact whole painted panel matched to restoration plate 48 and entry 48. The author inscription explicitly dates execution March 1705; the ensemble installation date 5 May 1705 is a separate event. The older colour reproduction differs from the restored image in tonal appearance but matches the complete composition. Exclude the separately indexed detail image.'),
7:dict(title='Apostles Andrew and Mark (Voshchatyn iconostasis)',end=1722,role='attributed_to',note='Exact paired-apostle panel matched to Volart image 57, explicitly captioned Voshchatyn. Helytovych p. 88 documents this ensemble, originally made for Zahoriv, completed in 1722 and transferred to the National Museum in Lviv in 1962. The author explains participation of assistants and uncertain divisions of hands. Retain a qualified attribution to Kondzelevych; no unsupported claim of sole autograph execution. The date of this individual panel stays unknown; 1722 is only the documented ensemble upper bound used in image review.'),
8:dict(title='Apostles Peter and Matthew (Voshchatyn iconostasis)',end=1722,role='attributed_to',note='Exact paired-apostle panel matched to Volart image 53, explicitly captioned Voshchatyn. This is a different physical panel from Andrew and Mark, and from the six single Bilostok apostles discussed separately in the museum article. The documented ensemble was completed in 1722; the precise panel execution date and division between master and assistants remain uncertain. Use attributed-to, not an unqualified autograph claim.'),
9:dict(title='Christ Pantocrator (Horodyshche)',end=1700,date_display='Late 17th century',medium='tempera and oil on lime wood, engraved and silvered gesso',dimensions='115 × 74 cm',acc='ВКМ І-109',note='Exact full composition, rainbow, open Gospel, angels and seraphim match the museum catalogue illustration on p. 189. The museum explicitly dates the icon late seventeenth century and identifies its origin in the Holy Trinity church at Horodyshche. Keep that verbal date without inventing a narrower numeric start year.'),
11:dict(title='Descent of the Holy Spirit (Bilostok)',end=1800,role='attributed_to',note='The two WikiArt Pentecost entries are photographs of the same Bilostok icon: select only this record and exclude row 14. Volart supplies the full composition and an early-eighteenth-century caption. Obukhovych p. 28 reports Ovsiichuk\'s attribution of this Bilostok subject to the early work of Kondzelevych. Retain attributed-to and an unknown catalogue year; the eighteenth-century source caption supports only the conservative pre-1801 image-date bound. No present church custody or museum holding is asserted.'),
12:dict(title='Mother of God Eleusa (Bilostok)',end=1800,role='attributed_to',medium='tempera on wood',note='Exact damaged central image matched to Volart image 7; Obukhovych p. 24 figure 10 reproduces the same face as a comparative detail, and p. 28 reports the attribution to early Kondzelevych. The publication says late seventeenth century while Volart says early eighteenth century. Keep the catalogue year unknown and attribution qualified. The approved source photograph covers the central painted image with visible conservation patches; it is not a photograph of the entire iconostasis. Preserve the complete supplied frame and do not repair or extend it.'),
13:dict(title='Saint George Slaying the Dragon (Bobly)',end=1800,date_display='Early 18th century',medium='tempera and oil on lime wood, engraving, silvering and gilding',dimensions='113 × 69 cm',acc='ВКМ РА-1064',note='Exact mounted saint, dragon, princess, castle and skull match the official museum catalogue p. 200 and Volart image 67. Reject the earlier proposed comparison with image 69, the distinct standing Saint George from Okorsk. Use the official 113 × 69 cm measurements; Volart gives 113 × 70 cm. Keep the verbal early-eighteenth-century date without inventing a numeric interval.'),
15:dict(title='Old Testament Trinity',end=1800,note='The selected octagonal three-angels-at-table image exactly matches Volart image 8. A similar Trinity occupies the top of the 1696 Zahoriv altar in Helytovych p. 84, while Volart also discusses Trinity compositions associated with the 1698–1705 Maniava ensemble. The exact ensemble assignment remains uncertain at the available reference resolution; do not convert that resemblance into a 1696 date or an accession number. Retain an unknown catalogue date. The documented seventeenth/eighteenth-century icon context supports a conservative pre-1801 image-date bound, not a modern reproduction date or artist-lifespan inference.')}
rows=[]
for i,d in data.items():
 row=copy.deepcopy(allrows[i-1]);w=row['work'];old=w['title'];note=d['note']
 row.update(selection_index=i,confidence=.96 if i in [1,7,8,11,12,15] else .99,editorial_review=note,image_identity_review='Original WikiArt reproduction visually inspected against saved comparison sheets and selected rendered museum publication pages. '+note)
 row['identity_basis']+=' '+note
 w.update(title=d['title'],alternate_title=old if old!=d['title'] else None,normalized_title=x.q.norm(d['title']),work_type='painting',medium_text=d.get('medium'),dimensions_text=d.get('dimensions'))
 if d.get('year'):w.update(creation_year_start=d['year'],creation_year_end=d['year'],date_display=str(d['year']),date_precision='exact')
 if d.get('date_display'):w['date_display']=d['date_display']
 if w['creation_year_start'] is None:
  row['date_review']=note+' Numeric creation years remain null under editorial review.'
  row['image_date_evidence']=dict(creation_year_end=d['end'],basis=note,classification='Conservative source-based image eligibility bound only; not a catalogue creation year')
 row['object_context']=dict(object_form='icon',cultural_context='Ukrainian Baroque icon painting; Volhynia and the Maniava monastic tradition',basis='WikiArt religious/icon genre, Volart object captions and cited museum scholarship identify this as a painted icon. '+note)
 if d.get('role'):row.update(attribution_role=d['role'],attribution_review=note)
 row['native_sources']=[dict(url=volurl,publisher='Volart: regional art research reference (supplemental, not the museum)',receipt=vol['receipt'],locator='Object image/caption crosswalk, research row '+str(i),facts=dict(subject=d['title'],comparison='Saved volart comparison sheets; corrected Bobly comparison for row 13',source_role='Supplemental object comparison and caption'),review=note,confidence=row['confidence'])]
 if i in [4,5,6]:
  entry={4:46,5:47,6:48}[i];pp={4:153,5:154,6:155}[i]
  row['native_sources'].append(pdf('restoration',f'Entry {entry}; PDF pages {pp-75} and {pp}; printed catalogue p. {pp+4}',dict(inventory=d['acc'],date='1698' if i==4 else '1705' if i==6 else '1698–1705',medium=d['medium'],dimensions=d.get('dimensions') or '147 × 92.5 × 2.5 cm in restoration catalogue',holding='National Museum in Lviv named after Andrey Sheptytsky'),note,d['acc']))
 if i in [1,4,5,6,7,8,15]:
  row['native_sources'].append(pdf('helytovych','pp. 77–89; especially 84, 86–88',dict(documented_ensembles=['Maniava/Bohorodchany 1698–1705','Zahoriv altar 1696','Voshchatyn/Zahoriv iconostasis completed 1722'],attribution_caution='The master worked with assistants; exact divisions of hands require study',holding='National Museum in Lviv; not Lviv National Art Gallery',current_display='No current display claim'),note))
 if i in [11,12]:row['native_sources'].append(pdf('volyn2017','pp. 24 and 28, L. Obukhovych',dict(attribution='V. Ovsiichuk attributed Bilostok Mother of God Eleusa and Descent of the Holy Spirit to early Kondzelevych',date_conflict='Late seventeenth versus early eighteenth century; exact year unresolved'),note))
 if i in [9,13]:row['native_sources'].append(pdf('catalogue','p. '+('189' if i==9 else '200–202'),dict(inventory=d['acc'],title=d['title'],date=d['date_display'],medium=d['medium'],dimensions=d['dimensions'],holding='Volyn Local History Museum / Museum of the Volyn Icon',provenance='Holy Trinity church, Horodyshche' if i==9 else 'Church of the Intercession, Bobly'),note,d['acc']))
 if i==5:
  u='https://nml.com.ua/collection/ikona-bogoroditsya-z-dityam-isusom/';v=x.r.load(x.RUN/'native-objects'/(x.r.sha(u.encode())+'.json'))
  row['native_sources'].append(dict(url=u,publisher='Andrey Sheptytsky National Museum in Lviv',receipt=v['receipt'],record_id='І-2289',facts=dict(title='Богородиця з Дитям Ісусом',dimensions='152 × 93 × 3 cm',inventory='І-2289'),review=note,confidence=.99))
 rows.append(row)
excluded={2:'Already catalogued Savior Not Made by Hands from Maniava.',3:'Already catalogued complete Maniava iconostasis; selected panels are components, not duplicate ensemble records.',10:'Conflicting Horodyshche versus Voshchatyn provenance and composite jamb image. Physical-object and attribution reconciliation incomplete.',14:'Same physical Bilostok Pentecost icon as selected row 11, despite different crop/photograph.'}
plan['rows']=rows
plan['held'] += [dict(title=v['work']['title'],source_url=v['source_url'],reason=excluded[i]) for i,v in enumerate(allrows,1) if i not in data]
plan.update(reviewed_at=x.r.now(),reviewer='Codex object-level and rendered primary-source visual review',research_limitations=['11 physical icon selections, four with explicit attributed-to creator links. Seven dates remain numerically unknown; broad source labels are retained.','No accepted holding links: the existing Lviv National Art Gallery is a different institution from the National Museum in Lviv. Volyn and NML holdings remain documented in citations pending exact institution records.','The Trinity ensemble assignment and Baptism medium are not resolved. No invented object inventory, precise year, current display, full-ensemble duplicate, detail-only duplicate or generated imagery.','Older WikiArt photographs may precede restoration and may omit decorative surrounds; full supplied image frames are preserved.'])
x.c.validate(plan)
x.r.save_gz(x.RUN/'reviewed-plan.json.gz',plan);x.r.save_gz(x.RUN/'image-selection.json.gz',plan)
x.r.save(x.RECOVERY/x.SLUG/'cloud-backup.json',x.r.load(x.RECOVERY/'cloud-backup.json'))
print(json.dumps(dict(new=len(rows),native_citations=sum(len(v['native_sources']) for v in rows),qualified=sum(v.get('attribution_role')=='attributed_to' for v in rows),source_bodies=x.c.validate(plan))))
